// Build-host generator for Dinit's Linux Bootstrap service package.
// Generated files use native Dinit service-description syntax.

#include <cerrno>
#include <cstring>
#include <fstream>
#include <iostream>
#include <string>
#include <sys/stat.h>

namespace {

bool make_directory(const std::string &path)
{
    if (mkdir(path.c_str(), 0755) == 0 || errno == EEXIST) return true;
    std::cerr << "dinit-bootstrap-gen: cannot create " << path
              << ": " << std::strerror(errno) << '\n';
    return false;
}

bool write_file(const std::string &path, const std::string &contents)
{
    std::ofstream output(path.c_str());
    if (!output) {
        std::cerr << "dinit-bootstrap-gen: cannot write " << path << '\n';
        return false;
    }
    output << contents;
    return output.good();
}

} // anonymous namespace

int main(int argc, char **argv)
{
    if (argc != 3) {
        std::cerr << "Usage: dinit-bootstrap-gen OUTPUT_DIR HELPER_PATH\n";
        return 2;
    }
    const std::string output_dir(argv[1]);
    const std::string helper_path(argv[2]);
    if (!make_directory(output_dir)) return 1;

    const std::string environment =
        "# Generated by dinit-bootstrap-gen. Do not edit this file.\n"
        "type = process\n"
        "command = " + helper_path + " detect --stay\n"
        "ready-notification = pipefd:4\n"
        "restart = false\n";
    const std::string proc =
        "# Generated by dinit-bootstrap-gen. Do not edit this file.\n"
        "type = scripted\n"
        "command = " + helper_path + " mount-pseudo proc\n"
        "restart = false\n"
        "depends-on: bootstrap-environment\n";
    const std::string sys =
        "# Generated by dinit-bootstrap-gen. Do not edit this file.\n"
        "type = scripted\n"
        "command = " + helper_path + " mount-pseudo sys\n"
        "restart = false\n"
        "depends-on: bootstrap-environment\n";
    const std::string pseudofs =
        "# Generated by dinit-bootstrap-gen. Do not edit this file.\n"
        "type = internal\n"
        "depends-on: bootstrap-proc\n"
        "depends-on: bootstrap-sys\n";
    const std::string early_prepare =
        "# Generated by dinit-bootstrap-gen. Do not edit this file.\n"
        "type = internal\n"
        "depends-on: pseudofs\n";

    if (!write_file(output_dir + "/bootstrap-environment", environment)) return 1;
    if (!write_file(output_dir + "/bootstrap-proc", proc)) return 1;
    if (!write_file(output_dir + "/bootstrap-sys", sys)) return 1;
    if (!write_file(output_dir + "/pseudofs", pseudofs)) return 1;
    if (!write_file(output_dir + "/early-prepare.target", early_prepare)) return 1;
    return 0;
}
